package com.cloudticket.promotion.api;
import com.cloudticket.common.security.RequirePermission; import com.cloudticket.promotion.persistence.entity.CouponEntity; import com.cloudticket.promotion.persistence.entity.CouponScopeEntity; import com.cloudticket.promotion.persistence.mapper.CouponMapper; import com.cloudticket.promotion.persistence.mapper.CouponScopeMapper; import java.time.Instant; import java.util.List; import java.util.Map; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/promotions/coupons") public class PromotionAdminController { private final CouponMapper coupons; private final CouponScopeMapper scopes; public PromotionAdminController(CouponMapper c,CouponScopeMapper s){coupons=c;scopes=s;}
 @RequirePermission("promotion:read") @GetMapping public Map<String,Object> list(){return Map.of("items",coupons.selectList(null));}
 @RequirePermission("promotion:write") @PostMapping public CouponEntity create(@RequestHeader("X-User-Id") String user,@RequestBody CouponEntity body){if(body.getName()==null||body.getName().isBlank())throw new IllegalArgumentException("name required");if(body.getTotalCount()==null||body.getTotalCount()<1)throw new IllegalArgumentException("totalCount invalid");if(body.getIssueBeginAt()==null)body.setIssueBeginAt(Instant.now());if(body.getIssueEndAt()==null||!body.getIssueEndAt().isAfter(body.getIssueBeginAt()))throw new IllegalArgumentException("issue window invalid");body.setId(UUID.randomUUID().toString());body.setCreatedBy(user);body.setStatus("DRAFT");body.setIssuedCount(0);body.setUsedCount(0);coupons.insert(body);return body;}
 @RequirePermission("promotion:publish") @PostMapping("/{id}/{action}") public Map<String,Object> status(@PathVariable String id,@PathVariable String action){CouponEntity c=coupons.selectById(id);if(c==null)throw new IllegalArgumentException("coupon not found");c.setStatus("publish".equalsIgnoreCase(action)?"PUBLISHED":"OFFLINE");coupons.updateById(c);return Map.of("id",id,"status",c.getStatus());}
 @RequirePermission("promotion:write") @PutMapping("/{id}/scopes") public Map<String,Object> scopes(@PathVariable String id,@RequestBody List<CouponScopeEntity> body){scopes.delete(com.baomidou.mybatisplus.core.toolkit.Wrappers.<CouponScopeEntity>lambdaQuery().eq(CouponScopeEntity::getCouponId,id));for(CouponScopeEntity row:body){row.setCouponId(id);if(row.getResourceId()==null)row.setResourceId("");scopes.insert(row);}return Map.of("id",id,"count",body.size());}
}
